using System.Runtime.InteropServices;

namespace VisionAlgorithm.OpenSrc.PatMax;

/// <summary>
/// Quantized coarse pose candidate generated by PatQuick probe matching (US 7,016,539) in base image coordinates.
/// </summary>
[StructLayout(LayoutKind.Sequential, Pack = 4)]
public readonly record struct CoarsePoseCandidate(
    float X,
    float Y,
    float AngleRadians,
    float Scale,
    float Score)
{
    public bool IsValid => Score > 0.0f && Scale > 0.0f;

    public static CoarsePoseCandidate Empty => default;
}
